import React from 'react';
import { Link } from 'react-router-dom';

const Navbar = ({ isAuthenticated, setAuth }) => {
  const handleLogout = () => {
    localStorage.removeItem('token');
    setAuth(false);
  };

  return (
    <nav style={{ backgroundColor: '#f8f9fa', padding: '10px', marginBottom: '20px' }}>
      <div style={{ maxWidth: '1200px', margin: '0 auto', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <h1 style={{ margin: 0 }}>My App</h1>
        <div>
          {isAuthenticated ? (
            <>
              <Link to="/dashboard" style={{ marginRight: '10px', textDecoration: 'none', color: '#007bff' }}>Dashboard</Link>
              <button onClick={handleLogout} style={{ padding: '5px 10px', backgroundColor: '#dc3545', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer' }}>
                Logout
              </button>
            </>
          ) : (
            <>
              <Link to="/login" style={{ marginRight: '10px', textDecoration: 'none', color: '#007bff' }}>Login</Link>
              <Link to="/register" style={{ textDecoration: 'none', color: '#28a745' }}>Register</Link>
            </>
          )}
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
